// Decides which workflows get CHECKED. It never decides what counts as published:
// error-workflow and sub-workflow targets always resolve against ALL published workflows,
// so a published-but-untagged sub-workflow is never misreported as unpublished.
const cfg = $('Set Configuration Parameters').first().json;
const tags = String(cfg.scopeTags || '').split(',').map((t) => t.trim().toLowerCase()).filter(Boolean);
const all = $input.all().map((i) => i.json);
const inScope = (w) => {
  if (!tags.length) return true;
  const names = (w.tags || []).map((t) => String((t && t.name) || '').toLowerCase());
  return tags.some((t) => names.includes(t));
};
return [{ json: {
  scopeLabel: tags.length ? 'workflows tagged ' + tags.join(' or ') : 'all published workflows',
  inScopeIds: all.filter(inScope).map((w) => String(w.id)),
  outOfScope: all.filter((w) => !inScope(w)).map((w) => String(w.name)),
  publishedCount: all.length,
} }];

// One item per in-scope workflow with an enabled Schedule Trigger, carrying the most
// recent time it SHOULD have fired, computed in that workflow's own timezone.
const cfg = $('Set Configuration Parameters').first().json;
const inScope = new Set($('Apply Workflow Scope').first().json.inScopeIds);
// Judge what actually runs: the published version, not the draft in the editor.
const nodesOf = (w) => (w.activeVersion && w.activeVersion.nodes) || w.nodes || [];
const pad = (n) => String(n).padStart(2, '0');

function lastFire(spec, tz) {
  const ref = DateTime.now().setZone(tz);
  const field = spec.field || 'days';
  const h = Number(spec.triggerAtHour ?? 0);
  const m = Number(spec.triggerAtMinute ?? 0);
  const at = (d) => d.set({ hour: h, minute: m, second: 0, millisecond: 0 });
  const hm = ' @ ' + pad(h) + ':' + pad(m);
  const nope = (reason, label) => ({ unverifiable: true, reason, label });
  const single = (n, unit) => (Number(n || 1) === 1 ? null : nope('every ' + n + ' ' + unit, 'every ' + n + ' ' + unit));

  // n8n cron ORs day-of-month with day-of-week, so it fires more often than it reads. Never guess.
  if (field === 'cronExpression') return nope('cron expression', String(spec.expression || 'cron'));
  if (field === 'seconds' || field === 'minutes') {
    const raw = Number(field === 'seconds' ? spec.secondsInterval || 30 : spec.minutesInterval || 5);
    const mins = field === 'seconds' ? Math.max(1, raw / 60) : raw;
    return { iso: ref.minus({ minutes: mins }).toISO(), toleranceMin: Math.max(15, mins * 3), label: 'every ' + raw + ' ' + field };
  }
  if (field === 'hours') {
    const n = Number(spec.hoursInterval || 1);
    return { iso: ref.minus({ hours: n }).toISO(), toleranceMin: Math.max(30, n * 60), label: 'every ' + n + 'h' };
  }
  if (field === 'days') {
    const bad = single(spec.daysInterval, 'days'); if (bad) return bad;
    let d = at(ref); if (d > ref) d = d.minus({ days: 1 });
    return { iso: d.toISO(), toleranceMin: 60, label: 'daily' + hm };
  }
  if (field === 'weeks') {
    const bad = single(spec.weeksInterval, 'weeks'); if (bad) return bad;
    const days = Array.isArray(spec.triggerAtDay) ? spec.triggerAtDay.map(Number) : [0];
    for (let back = 0; back <= 7; back++) {
      const d = at(ref.minus({ days: back }));
      // Luxon weekday is 1=Mon..7=Sun; n8n triggerAtDay is 0=Sun..6=Sat.
      if (d <= ref && days.includes(d.weekday % 7)) return { iso: d.toISO(), toleranceMin: 60, label: 'weekly [' + days.join(',') + ']' + hm };
    }
    return nope('no matching weekday', 'weekly');
  }
  if (field === 'months') {
    const bad = single(spec.monthsInterval, 'months'); if (bad) return bad;
    const dom = Number(spec.triggerAtDayOfMonth || 1);
    for (let back = 0; back <= 12; back++) {
      const mo = ref.startOf('month').minus({ months: back });
      if (dom > mo.daysInMonth) continue; // n8n skips months that lack this day
      const d = at(mo.set({ day: dom }));
      if (d <= ref) return { iso: d.toISO(), toleranceMin: 60, label: 'monthly on day ' + dom + hm };
    }
    return nope('no matching day of month', 'monthly');
  }
  return nope("unrecognised interval '" + field + "'", String(field));
}

const out = [];
for (const { json: wf } of $('Get Published Workflows').all()) {
  if (!inScope.has(String(wf.id))) continue;
  const triggers = nodesOf(wf).filter((n) => n.type === 'n8n-nodes-base.scheduleTrigger' && !n.disabled);
  if (!triggers.length) continue;
  const ownTz = wf.settings && wf.settings.timezone;
  const tz = ownTz && ownTz !== 'DEFAULT' ? String(ownTz) : cfg.defaultTimezone;
  const specs = triggers.flatMap((t) => {
    const iv = t.parameters && t.parameters.rule && t.parameters.rule.interval;
    return Array.isArray(iv) && iv.length ? iv : [{ field: 'days' }];
  });
  let best = null; const labels = []; const reasons = [];
  for (const spec of specs) {
    const r = lastFire(spec, tz);
    labels.push(r.label);
    if (r.unverifiable) reasons.push(r.reason);
    else if (!best || r.iso > best.iso) best = r;
  }
  out.push({ json: {
    workflowId: String(wf.id), workflowName: String(wf.name), createdAt: wf.createdAt || null, tz,
    scheduleLabel: labels.join(' + '),
    expectedLastFireISO: best ? best.iso : null, toleranceMin: best ? best.toleranceMin : 60,
    unverifiable: !best, unverifiableReason: reasons.join('; '),
  } });
}
// Nothing scheduled in scope: emit a placeholder so the run still reaches the digest
// instead of stopping here with zero items.
return out.length ? out : [{ json: { workflowId: String($workflow.id), placeholder: true } }];

// Check B - scheduled workflows that did not fire. The only way to see a schedule
// that silently stopped: nothing errors, there is simply no execution.
const cfg = $('Set Configuration Parameters').first().json;
const now = DateTime.now();
const cutoff = now.minus({ hours: Number(cfg.lookbackHours || 24) });

const lastRun = {};
for (const { json: e } of $input.all()) {
  // A manual test run after the expected time must not hide a missed schedule.
  if (!e.workflowId || !e.startedAt || e.mode === 'manual') continue;
  const k = String(e.workflowId);
  if (!lastRun[k] || String(e.startedAt) > lastRun[k]) lastRun[k] = String(e.startedAt);
}

const missed = [];
const unverifiable = [];
const scheduled = $('Identify Scheduled Workflows').all().map((i) => i.json).filter((s) => !s.placeholder);
for (const s of scheduled) {
  if (s.unverifiable) { unverifiable.push({ id: s.workflowId, name: s.workflowName, why: 'schedule: ' + s.unverifiableReason }); continue; }
  const exp = DateTime.fromISO(String(s.expectedLastFireISO)).setZone(s.tz);
  if (!exp.isValid) continue;
  if (exp.plus({ minutes: Number(s.toleranceMin || 60) }) > now) continue; // still in its grace window
  // Report a miss ONCE. Otherwise a weekly job that missed one Friday nags every day
  // until next Friday, and the alert gets muted.
  if (exp < cutoff) continue;
  if (s.createdAt && DateTime.fromISO(String(s.createdAt)) > exp) continue; // did not exist yet
  const last = lastRun[s.workflowId] ? DateTime.fromISO(lastRun[s.workflowId]).setZone(s.tz) : null;
  if (last && last >= exp.minus({ minutes: 5 })) continue;
  missed.push({
    id: s.workflowId, name: s.workflowName, schedule: s.scheduleLabel,
    expected: exp.toFormat('ccc dd LLL HH:mm') + ' ' + exp.toFormat('ZZZZ'),
    lastRun: last ? last.toFormat('ccc dd LLL HH:mm') : 'never',
  });
}
return [{ json: { missed, unverifiable, scheduledCount: scheduled.length } }];

// Check A - executions that errored inside the lookback window.
// 'waiting' is deliberately NOT a fault: a run parked on a human approval or a Wait node
// sits there for hours or days by design.
const cfg = $('Set Configuration Parameters').first().json;
const cutoff = DateTime.now().minus({ hours: Number(cfg.lookbackHours || 24) });
const inScope = new Set($('Apply Workflow Scope').first().json.inScopeIds);
const names = {};
for (const { json: w } of $('Get Published Workflows').all()) names[String(w.id)] = String(w.name);

const byWf = {};
for (const { json: e } of $('Get Recent Error Logs').all()) {
  if (!e.id || e.status !== 'error' || !inScope.has(String(e.workflowId))) continue;
  const t = DateTime.fromISO(String(e.startedAt));
  if (!t.isValid || t < cutoff) continue;
  const k = String(e.workflowId);
  const row = byWf[k] || (byWf[k] = { id: k, name: names[k] || k, count: 0, latest: '', execId: '' });
  row.count++;
  if (String(e.startedAt) > row.latest) { row.latest = String(e.startedAt); row.execId = String(e.id); }
}
return [{ json: { ...$input.first().json, errored: Object.values(byWf) } }];

// Check C - workflows that would fail silently. Four ways to look protected and not be.
// The last two look configured in the UI and are dead: n8n accepts the setting, then
// cannot run the target. Resolve the pointer, never just check the field is filled in.
const all = $('Get Published Workflows').all().map((i) => i.json);
const byId = {};
for (const w of all) byId[String(w.id)] = w; // ALL published, so targets resolve correctly
const inScope = new Set($('Apply Workflow Scope').first().json.inScopeIds);
const nodesOf = (w) => (w.activeVersion && w.activeVersion.nodes) || w.nodes || []; // published, not draft

const unprotected = [];
for (const w of all) {
  const id = String(w.id);
  if (!inScope.has(id)) continue;
  const raw = String((w.settings && w.settings.errorWorkflow) || '');
  const ew = raw === 'DEFAULT' ? '' : raw;
  const target = ew ? byId[ew] : null;
  const hasErrTrigger = nodesOf(w).some((n) => n.type === 'n8n-nodes-base.errorTrigger' && !n.disabled);
  let why = '';
  if (ew && ew === id) why = 'error workflow points at itself';
  else if (ew && !target) why = 'error workflow ' + ew + ' is not published, so n8n cannot run it';
  else if (target && target.settings && target.settings.callerPolicy === 'none') why = "error workflow '" + target.name + "' refuses all callers";
  else if (!ew && !hasErrTrigger) why = 'no error workflow and no Error Trigger: failures are silent';
  if (why) unprotected.push({ id, name: String(w.name), why });
}
return [{ json: { ...$input.first().json, unprotected } }];

// Check D - the same pointer rule, applied to sub-workflow calls. An unpublished or
// locked sub-workflow refuses every call, and depending on how the caller handles that
// it can keep reporting success. Checks A-C cannot see this at all.
const all = $('Get Published Workflows').all().map((i) => i.json);
const byId = {};
for (const w of all) byId[String(w.id)] = w;
const inScope = new Set($('Apply Workflow Scope').first().json.inScopeIds);
const nodesOf = (w) => (w.activeVersion && w.activeVersion.nodes) || w.nodes || []; // published, not draft
const CALLERS = ['n8n-nodes-base.executeWorkflow', 'n8n-nodes-base.toolWorkflow'];

const prev = $input.first().json;
const unverifiable = [...prev.unverifiable];
const brokenSubcalls = [];
for (const w of all) {
  const id = String(w.id);
  if (!inScope.has(id)) continue;
  for (const n of nodesOf(w)) {
    if (!CALLERS.includes(n.type) || n.disabled) continue;
    const p = n.parameters || {};
    if (p.source && p.source !== 'database') continue; // url / parameter / localFile carry no id
    const ref = p.workflowId;
    const targetId = String((ref && typeof ref === 'object' ? ref.value : ref) || '');
    if (!targetId) continue;
    const at = { id, name: String(w.name), node: String(n.name) };
    // A target picked by expression cannot be resolved statically. Say so, never call it OK.
    if (targetId.startsWith('=') || targetId.includes('{{')) { unverifiable.push({ id, name: at.name, why: "node '" + at.node + "' picks its sub-workflow by expression" }); continue; }
    const t = byId[targetId];
    const policy = t && t.settings ? String(t.settings.callerPolicy || '') : '';
    const allowed = t && t.settings ? String(t.settings.callerIds || '').split(',').map((s) => s.trim()) : [];
    if (!t) brokenSubcalls.push({ ...at, why: 'calls ' + targetId + ', which is not published: every call is refused' });
    else if (policy === 'none') brokenSubcalls.push({ ...at, why: "sub-workflow '" + t.name + "' refuses all callers" });
    else if (policy === 'workflowsFromAList' && !allowed.includes(id)) brokenSubcalls.push({ ...at, why: "sub-workflow '" + t.name + "' allow-list does not include this caller" });
  }
}
return [{ json: { ...prev, unverifiable, brokenSubcalls } }];

const cfg = $('Set Configuration Parameters').first().json;
const scope = $('Apply Workflow Scope').first().json;
const r = $input.first().json;
const tz = cfg.defaultTimezone;
const now = DateTime.now().setZone(tz);
let base = String(cfg.instanceUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const a = (path, label) => (base ? '<a href="' + esc(base + path) + '">' + esc(label) + '</a>' : esc(label));
const wf = (x) => a('/workflow/' + x.id, x.name);
const when = (iso) => DateTime.fromISO(String(iso)).setZone(tz).toFormat('ccc dd LLL HH:mm');
const table = (title, intro, head, rows) => !rows.length ? '' :
  '<h3>' + title + ' (' + rows.length + ')</h3>' + (intro ? '<p>' + intro + '</p>' : '') +
  '<table border=1 cellpadding=6 cellspacing=0><tr>' + head.map((h) => '<th align=left>' + h + '</th>').join('') + '</tr>' +
  rows.map((c) => '<tr><td>' + c.join('</td><td>') + '</td></tr>').join('') + '</table>';

const ok = !r.errored.length && !r.missed.length && !r.unprotected.length && !r.brokenSubcalls.length;
const hb = Number(cfg.heartbeatWeekday || 0);
// Weekly all-clear: without it, a dead health check looks exactly like a healthy instance.
const heartbeat = ok && hb > 0 && now.weekday === hb;

let html = '<p>n8n health for the ' + esc(cfg.lookbackHours) + 'h ending ' + esc(now.toFormat('ccc dd LLL yyyy HH:mm')) + ' (' + esc(tz) + ').</p>';
if (heartbeat) html += '<p><b>All clear.</b> This weekly note confirms the health check itself is still running.</p>';
html += table('Errored', '', ['Workflow', 'Runs', 'Latest'],
  r.errored.map((e) => [wf(e), e.count, a('/workflow/' + e.id + '/executions/' + e.execId, when(e.latest))]));
html += table('Broken sub-workflow calls', 'These fail at runtime, and the caller may still report success. Fix these first.', ['Workflow', 'Node', 'Problem'],
  r.brokenSubcalls.map((b) => [wf(b), esc(b.node), esc(b.why)]));
html += table('Did not fire', '', ['Workflow', 'Schedule', 'Expected', 'Last run'],
  r.missed.map((m) => [wf(m), esc(m.schedule), esc(m.expected), esc(m.lastRun)]));
html += table('No failure path', '', ['Workflow', 'Problem'],
  r.unprotected.map((u) => [wf(u), esc(u.why)]));
// Only alongside a real finding: on their own these repeat daily and train you to ignore the mail.
if (!ok && r.unverifiable.length) html += table('Not verifiable', 'Reported, never assumed healthy.', ['Workflow', 'Why'], r.unverifiable.map((u) => [wf(u), esc(u.why)]));
html += "<p style='color:#888'>Checked " + scope.inScopeIds.length + ' of ' + scope.publishedCount + ' published workflows (' + esc(scope.scopeLabel) + '), ' + r.scheduledCount + ' of them scheduled. Read-only.</p>';
if (!ok && scope.outOfScope.length) html += "<p style='color:#888'>Not monitored (" + scope.outOfScope.length + '): ' + esc(scope.outOfScope.join(', ')) + '. Tag them to bring them into scope.</p>';

const counts = { errored: r.errored.length, brokenSubcalls: r.brokenSubcalls.length, missed: r.missed.length, unprotected: r.unprotected.length, unverifiable: r.unverifiable.length };
const subject = ok
  ? '[n8n health] All clear: ' + scope.inScopeIds.length + (scope.inScopeIds.length === 1 ? ' workflow' : ' workflows') + ' checked'
  : '[n8n health] ' + counts.errored + ' errored, ' + counts.brokenSubcalls + ' broken sub-calls, ' + counts.missed + ' missed, ' + counts.unprotected + ' unprotected';
return [{ json: { ok, sendEmail: !ok || heartbeat, subject, ...counts, summaryHtml: html } }];
